import {protocolVersion} from './format.mjs';

export const csvRow = (values) => {
  if (values.length === 0) return '';

  // Quote cell logic for special characters
  const quoteCell = (cell) => {
    if (/",|\r|\n/.test(cell)) {
      const escapedContents = cell.replace(/\"/g, '""'); // Double each existing "
      return (`"${escapedContents}"`);
    }
    return cell;
  };


  // Convert array of cells to CSV row string
  const convertedCells = values.map((value) => quoteCell(value));
  return convertedCells.join(',');
};

