export const protocolVersion  = 1;

export const csvRow =(values) => {
    if (values.length === 0) return '';

    // Helper function to properly format each cell
    const shouldQuote = (cell) => /[,\\r\\n"]/.test(cell);
    const escapeCell = (cell) => {
        let escaped = cell;
        if (shouldQuote(cell)) {
            escaped = (`"${escaped.replace(/\"/g, '""')}"`);
        }
        return escaped;
    };

    // Process all values through escapeCell to handle quoting, escaping
    return values.map(escapeCell).join(',');
};

